FUEL_ON_BOARD = {"de": ", {x} Pfund an Bord", "fr": ", {x} livres à bord", "es": ", {x} libras a bordo", "it": ", {x} libbre a bordo", "pt": ", {x} libras a bordo", "nl": ", {x} pond aan boord",
                 "pl": ", {x} funtów na pokładzie", "sv": ", {x} pund ombord", "ru": ", {x} фунтов на борту", "zh": "，机上{x}磅"}

_CACHE: dict[str, list[tuple[str, str]]] = {}
_ZH_PERCENT = re.compile(r"百分之([\d零一二两三四五六七八九十]+)")


def _phrases(code: str) -> list[tuple[str, str]]:
    if code not in _CACHE:
        found = {said if code == "zh" else plain(said): english for english, words in HEARD[code].items() for said in words.split("|")}
        _CACHE[code] = sorted(found.items(), key=lambda kv: -len(kv[0]))
    return _CACHE[code]


def as_english(text: str, code: str) -> str:
    """``text`` said in language ``code``, with what the ramp knows of it in the English their grammar reads. What isn't known stays:
    the grammar passes over it. A number said as words comes out in digits. Said in English, it's left as it is."""
    if code not in HEARD or not text.strip():
        return text
    if code == "zh":
        said = zh_whole_numbers(_ZH_PERCENT.sub(lambda m: f"{zh_whole_numbers(m[1]) if not m[1].isdigit() else m[1]}%", text.lower()))
        said = re.sub(r"[，。！？、,.!?]+", " ", said)
        for words, english in _phrases(code):
            said = said.replace(words, f" {english} ")
        return " ".join(said.split())
    said = plain(text)
    for words in (plain(w) for w in HEARD[code]["percent"].split("|")):  # (before the numbers: "pour cent" isn't a hundred)
        said = re.sub(rf"\b{words}\b", "percent", said)
    said = whole_numbers(said, code).replace(".", " ").replace(",", " ")
    said = f" {' '.join(said.split())} "
    for words, english in _phrases(code):
        said = said.replace(f" {words} ", f" {english} ")
    return " ".join(said.split())
